INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Werden Zuschlagssätze in der Leistungsrechnung verwendet, um Gemeinkosten zu verteilen?', 2, '[{"text": "Ja", "correct": true, "because": "Zuschlagssätze dienen der Gemeinkostenverteilung"}, {"text": "Nein", "correct": false, "because": "Verteilung ist Hauptzweck"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Zuschlagssätze in der Leistungsrechnung auch auf Einzelkosten angewendet werden?', 2, '[{"text": "Ja", "correct": false, "because": "Einzelkosten sind direkt, Zuschläge für Gemeinkosten"}, {"text": "Nein", "correct": true, "because": "Zuschläge betreffen indirekte Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Zuschlagssätze in der Leistungsrechnung immer in Prozent angegeben?', 2, '[{"text": "Ja", "correct": true, "because": "Prozentuale Angabe ist Standard"}, {"text": "Nein", "correct": false, "because": "Prozent ist üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein falscher Zuschlagssatz die Kalkulation von Leistungen verfälschen?', 2, '[{"text": "Ja", "correct": true, "because": "Ungenauigkeit beeinflusst Kosten"}, {"text": "Nein", "correct": false, "because": "Verfälschung ist möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Zuschlagssätze regelmäßig überprüft und angepasst werden?', 2, '[{"text": "Ja", "correct": true, "because": "Anpassung an Kostenänderungen nötig"}, {"text": "Nein", "correct": false, "because": "Regelmäßige Überprüfung ist sinnvoll"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Was ist die Hauptfunktion von Zuschlagssätzen in der Leistungsrechnung?', 2, '[{"text": "Verteilung von Gemeinkosten auf Kostenobjekte", "correct": true, "because": "Primäre Aufgabe"}, {"text": "Festlegung der Einzelkosten", "correct": false, "because": "Einzelkosten sind direkt"}, {"text": "Berechnung der Verkaufspreise", "correct": false, "because": "Folgeschritt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kostenart wird mit Zuschlagssätzen in der Leistungsrechnung verteilt?', 3, '[{"text": "Gemeinkosten", "correct": true, "because": "Indirekte Kosten werden zugeschlagen"}, {"text": "Einzelkosten", "correct": false, "because": "Direkt zurechenbar"}, {"text": "Fixkosten", "correct": false, "because": "Nur Teil der Gemeinkosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie wird ein Zuschlagssatz in der Leistungsrechnung typischerweise berechnet?', 2, '[{"text": "Gemeinkosten geteilt durch Einzelkosten", "correct": true, "because": "Standardformel"}, {"text": "Einzelkosten geteilt durch Umsatz", "correct": false, "because": "Falsche Basis"}, {"text": "Fixkosten geteilt durch Arbeitszeit", "correct": false, "because": "Nicht üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was passiert, wenn ein Zuschlagssatz zu hoch angesetzt wird?', 3, '[{"text": "Überdeckung der Gemeinkosten", "correct": true, "because": "Kosten werden überbewertet"}, {"text": "Senkung der Einzelkosten", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Reduzierung der Fixkosten", "correct": false, "because": "Keine Verbindung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Grundlage wird oft für Zuschlagssätze in der Leistungsrechnung genutzt?', 2, '[{"text": "Einzelkosten", "correct": true, "because": "Verteilungsgrundlage"}, {"text": "Gesamtkosten", "correct": false, "because": "Zu allgemein"}, {"text": "Produktionsvolumen", "correct": false, "because": "Nicht immer präzise"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Welche Gemeinkosten können mit Zuschlagssätzen in der Leistungsrechnung verteilt werden?', 4, '[{"text": "Fertigungs-Gemeinkosten", "correct": true, "because": "Häufig verteilt"}, {"text": "Verwaltungs-Gemeinkosten", "correct": true, "because": "Ebenfalls zugeschlagen"}, {"text": "Direkte Materialkosten", "correct": false, "because": "Einzelkosten"}, {"text": "Vertriebs-Gemeinkosten", "correct": true, "because": "Indirekte Kosten"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren beeinflussen die Höhe eines Zuschlagssatzes?', 3, '[{"text": "Höhe der Gemeinkosten", "correct": true, "because": "Direkter Einfluss"}, {"text": "Einzelkostenbasis", "correct": true, "because": "Verteilungsgrundlage"}, {"text": "Verkaufspreise", "correct": false, "because": "Folge, kein Einfluss"}, {"text": "Produktionsmenge", "correct": true, "because": "Kann die Basis beeinflussen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein falsch angesetzter Zuschlagssatz in der Leistungsrechnung haben?', 4, '[{"text": "Überbewertung der Produktkosten", "correct": true, "because": "Zu hoher Satz"}, {"text": "Unterdeckung der Gemeinkosten", "correct": true, "because": "Zu niedriger Satz"}, {"text": "Senkung der Fixkosten", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Verfälschte Leistungskalkulation", "correct": true, "because": "Kostenstruktur falsch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Nutzung von Zuschlagssätzen in der Leistungsrechnung?', 3, '[{"text": "Einfache Verteilung von Gemeinkosten", "correct": true, "because": "Praktikabel"}, {"text": "Genauere Kostenzuordnung", "correct": true, "because": "Kosten werden verteilt"}, {"text": "Reduzierung der Gemeinkosten", "correct": false, "because": "Kein direkter Effekt"}, {"text": "Klarheit in der Kalkulation", "correct": true, "because": "Transparenz erhöht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Schritte sind bei der Anwendung von Zuschlagssätzen nötig?', 3, '[{"text": "Ermittlung der Gemeinkosten", "correct": true, "because": "Ausgangspunkt"}, {"text": "Festlegung der Einzelkostenbasis", "correct": true, "because": "Verteilungsgrundlage"}, {"text": "Festsetzung der Verkaufspreise", "correct": false, "because": "Folgeschritt"}, {"text": "Berechnung des prozentualen Satzes", "correct": true, "because": "Ergebnis der Methode"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Zuschlagssätze verteilen Gemeinkosten in der Leistungsrechnung. b) Sie werden auf Fixkosten angewendet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Gemeinkosten)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Zuschlagssätze sind in Prozent angegeben. b) Sie betreffen nur Einzelkosten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Gemeinkosten)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein zu hoher Zuschlagssatz überbewertet Kosten. b) Zuschlagssätze sind unveränderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (anpassbar)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Zuschlagssätze verbessern die Kalkulation von Leistungen. b) Sie werden ohne Gemeinkosten berechnet.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "a) richtig, b) falsch (Gemeinkosten nötig)"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Falsche Zuschlagssätze verfälschen die Leistungsrechnung. b) Sie sind ein Werkzeug der Kostenverteilung.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Beides ist richtig"}, {"text": "Beides stimmt", "correct": true, "because": "a) Verfälschung, b) Verteilung"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "Beides ist richtig"}]');
